// The benchmark replays the SIM_SEQ the notebook generated (and validated
// against the supervisors). Reproducible, and directly comparable with the
// single-board sketch. Each node walks its own share and the nodes meet at
// shared events. A step that cannot fire is reported and skipped, never forced.
//
// There is deliberately no free-running driver. One existed — each node fired
// whatever its own supervisors allowed — and it produced traces no plant could:
// a supervisor only forbids what the specification requires, it is not a model
// of the machines (a reduced one even less so), so it happily fired "start
// machine 1" five times in a row. Generating plausible traces needs the plant
// model, which the generated header does not carry.

// How long to wait for one SIM_SEQ step before declaring it inadmissible.
#ifndef DES_STEP_TIMEOUT_MS
#define DES_STEP_TIMEOUT_MS 10000
#endif

#ifndef DES_ROUNDS
#define DES_ROUNDS 5                  // production cycles in the benchmark
#endif
#ifndef DES_WORK_MS
#define DES_WORK_MS 250               // simulated machine processing time
#endif

// ── transaction tuning ──────────────────────────────────────────────────────
// timeout × retries must cover the longest homomorphic step any participant
// can be in when a request arrives: frames keep being RECEIVED during a step
// (he_yield), but they are only ACTED ON when it ends, and one step was
// measured at 3-4 s on `fms`. 1.5 s × 4 tries = 6 s. At 250 ms the initiator
// gave up on commits the peer was about to accept perfectly well.
#ifndef DES_REQ_TIMEOUT_MS
#define DES_REQ_TIMEOUT_MS 1500
#endif
#ifndef DES_ACK_TIMEOUT_MS
#define DES_ACK_TIMEOUT_MS 1500
#endif
#ifndef DES_REQ_RETRIES
#define DES_REQ_RETRIES 4             // failure here is harmless — nothing applied
#endif
#ifndef DES_ACK_RETRIES
#define DES_ACK_RETRIES 5             // failure here forces a SAFE HALT
#endif
#ifndef DES_LOCK_TIMEOUT_MS
#define DES_LOCK_TIMEOUT_MS 2000      // frees a lock held by a dead initiator
#endif
#ifndef DES_RENDEZVOUS_MS
#define DES_RENDEZVOUS_MS 20000
#endif

// Bench-only artificial frame loss (%), applied on receive so the sender still
// counts a transmit and the retransmit path is genuinely exercised.
#ifndef DES_SIMULATE_LOSS_PCT
#define DES_SIMULATE_LOSS_PCT 0
#endif

// Lockstep makes every node walk the WHOLE SIM_SEQ, announcing even its purely
// local events so the others can keep a synchronised replay. It buys a
// reproducible global trace, and it costs a frame per local event plus a
// homomorphic step on every node for an event that concerns only one of them.
//
// It is OFF by default: without it each node walks only its own projection of
// the trace and the nodes meet at shared events, which is all the supervisors
// need. Lockstep makes the slowest node pace every step of every node — on FMS
// one board owes 3-4 s per shared apply — for a global interleaving nothing
// else depends on. Turn it on for small problems where one reproducible
// interleaving matters more than throughput.
#ifndef DES_BENCH_LOCKSTEP
#define DES_BENCH_LOCKSTEP 0
#endif

// Cross-check every decision against the MONOLITHIC supervisor from the same
// header. Only possible with DES_BENCH_LOCKSTEP 1 (a node must see every event
// to replay the trace) and a header that has one; the summary says when it is
// off and why.
#ifndef DES_VERIFY_MONO
#define DES_VERIFY_MONO 1
#endif

// Plant-check demonstration. At step DES_INJECT_AT_STEP of cycle 1, the owner of
// event DES_INJECT_EVENT acts as if a sensor had just reported it and prints
// whether the plant check would accept it. Nothing is applied, so the run is
// otherwise unchanged. Off unless DES_INJECT_EVENT is defined, e.g.
//   #define DES_INJECT_EVENT   "12"   // "conveyor C1 finished"...
//   #define DES_INJECT_AT_STEP 0      // ...before C1 was ever started
#ifndef DES_INJECT_AT_STEP
#define DES_INJECT_AT_STEP 0
#endif

